"""Small Markdown helpers shared by the page writers."""

from __future__ import annotations

import re
import textwrap


def header(*sources: str) -> str:
    """The comment at the top of every generated page."""
    return (
        "<!-- Generated by docs/build.py from "
        + ", ".join(sources)
        + ". Do not edit this file: change its sources and run `pixi run docs`. -->\n\n"
    )


def cell(text) -> str:
    """Text made safe for a table cell."""
    return str(text).replace("|", "\\|").replace("\n", " ").strip()


def table(head: list[str], rows: list[list[str]], align: list[str] | None = None) -> str:
    align = align or ["left"] * len(head)
    marks = {"left": ":--", "right": "--:", "center": ":-:"}
    out = "| " + " | ".join(cell(h) for h in head) + " |\n"
    out += "| " + " | ".join(marks[a] for a in align) + " |\n"
    for row in rows:
        out += "| " + " | ".join(cell(c) for c in row) + " |\n"
    return out + "\n"


def indent(text: str, n: int = 4) -> str:
    return textwrap.indent(text, " " * n, lambda line: line.strip() != "")


def tabs(items: list[tuple[str, str]]) -> str:
    """Content tabs; a single item is written without a tab."""
    if len(items) == 1:
        return items[0][1]
    out = ""
    for title, body in items:
        out += f'=== "{title}"\n\n{indent(body)}\n'
    return out


def admonition(kind: str, title: str, body: str) -> str:
    return f'!!! {kind} "{title}"\n\n{indent(body)}\n'


def admonition_collapsed(kind: str, title: str, body: str) -> str:
    """A box that opens when clicked (pymdownx.details)."""
    return f'??? {kind} "{title}"\n\n{indent(body)}\n'


def plain(text: str) -> str:
    """Collapse the line breaks and double spaces of YAML-folded text."""
    return re.sub(r"\s+", " ", str(text or "")).strip()


def placeholders_as_code(text: str) -> str:
    return re.sub(r"(\{[a-z_]+\})", r"`\1`", text)


def number(text: str) -> str:
    """A value as written in the process file, with thousands separators."""
    try:
        f = float(text)
    except ValueError:
        return text
    if f.is_integer() and abs(f) >= 1000 and "." not in text:
        return f"{int(f):,}"
    return text


def value(text: str, unit: str, suffix: str = "") -> str:
    """'1.14' and 'mm' -> '1.14 mm'; '60', '%', 'of nominal wall' -> '60% of nominal wall'."""
    if not text:
        return "–"
    if text.upper() in ("ERROR", "WARNING"):
        return text.capitalize()
    n = number(text)
    if unit in ("%", "°", "×"):
        out = f"{n}{unit}"
    elif unit:
        out = f"{n} {unit}"
    else:
        out = n
    return f"{out} {suffix}" if suffix else out
